func TestAltMirrorsClass(t *testing.T) {
	tr := newTree(t)
	tr.set("phase=building", "target="+revB)
	if v := tr.render(); v.Alt != v.Class || v.Alt == "" {
		t.Fatalf("alt = %q, class = %q", v.Alt, v.Class)
	}
}

